// Missing EOS curvature gate on SAME saved controls and SAVED new RHS.
// No factory, trajectory, physical heat regeneration or mass/RHS solve.
#define GFS_GEOMETRIC_PRESSURE_LIBRARY
#include "test_geometric_pressure_v1.cpp"
struct Temporal {R A=0,QJ=0,QdJ=0,QddJ=0,Vdd=0,delta=0,delta_dot=0,delta_ddot=0,mean=0,correction_mean=0,sum_nuddot=0;};
static std::array<rhs::Vec,2> load_acceleration(const std::string&path,const st::Factory&f){
    std::array<rhs::Vec,2>a={rhs::Vec(f.dof.size()),rhs::Vec(f.dof.size())};std::vector<bool>seen(f.dof.size());std::ifstream input(path);need(bool(input),"saved new pressure acceleration");std::string line;std::getline(input,line);while(std::getline(input,line)){unsigned long long id;int owner;R ax,ay,Fx,Fy;need(sscanf(line.c_str(),"%llu,%d,%Lg,%Lg,%Lg,%Lg",&id,&owner,&ax,&ay,&Fx,&Fy)==6&&id<f.dof.size()&&!seen[id]&&owner==f.dof[id].owner,"same saved sparse acceleration owner");seen[id]=true;a[0][id]=ax;a[1][id]=ay;}for(bool yes:seen)need(yes,"complete saved acceleration");return a;
}
static std::vector<R> hessian_velocity(const st::Factory&f,const gp::Geometry&G){
    std::vector<R>out(f.cell.size());std::vector<double>x,w;st::gauss(64,x,w);
    for(const auto&e:G.edge){gp::V2 v[6];for(int j=0;j<e.n;j++){const auto&q=f.coefficient[e.id[j]];v[j]={q.v[0],q.v[1]};}auto d=v[3]-v[0];R area=gp::cross(v[0],v[3])/2;
        for(int k=0;k<64;k++){R beta[6]={},dbeta[6]={},N[6]={};gp::edge_shapes(e.reference,x[k],beta,dbeta,N);auto c1=(v[1]-v[0])-(1.L/3)*d,c2=(v[2]-v[0])-(2.L/3)*d;auto delta=beta[1]*c1+beta[2]*c2,prime=dbeta[1]*c1+dbeta[2]*c2;for(int j=4;j<e.n;j++){delta=delta+beta[j]*v[j];prime=prime+dbeta[j]*v[j];}area+=R(w[k])*(gp::cross(delta,d)+.5L*gp::cross(delta,prime));}
        for(const auto&s:e.side)out[s.cell]+=2*R(s.sign)*area;
    }return out;
}
struct PointTemporal {GfsMaterialPoint12 p;R Jdot,Jddot;};
static PointTemporal point_temporal(const st::Factory&f,const STPoint&q,const std::array<rhs::Vec,2>&a){
    const auto&t=f.triangle[q.triangle];STJet N[ST_MAX];PointTemporal out;need(st_shape(t,q,N)&&st_point(t,f.coefficient.data(),N,&out.p),"same saved point temporal derivatives");R D[4]={};for(int j=0;j<t.n;j++)for(int d=0;d<2;d++){D[2*d]+=a[d][t.id[j]]*N[j].x;D[2*d+1]+=a[d][t.id[j]]*N[j].y;}const auto&p=out.p;R divergence=(D[0]*p.F[3]-D[1]*p.F[2]-D[2]*p.F[1]+D[3]*p.F[0])/p.J,divv=R(p.grad_v[0])+p.grad_v[3],trace=R(p.grad_v[0])*p.grad_v[0]+2*R(p.grad_v[1])*p.grad_v[2]+R(p.grad_v[3])*p.grad_v[3];out.Jdot=R(p.J)*divv;out.Jddot=R(p.J)*(divv*divv+divergence-trace);return out;
}
int main(int argc,char**argv){int provided;MPI_Init_thread(&argc,&argv,MPI_THREAD_FUNNELED,&provided);int rank,ranks;MPI_Comm_rank(MPI_COMM_WORLD,&rank);MPI_Comm_size(MPI_COMM_WORLD,&ranks);int code=2;
    try{need(argc==5,"original packet SAVED controls SAVED new pressure run NEW output");auto packet=curved::read(argv[1]);std::string saved=argv[2],pressure=argv[3],dest=argv[4];bool all=true;
        for(int state=0;state<2;state++){std::string name=state?"finite":"initial";auto f=load_saved(saved+(state?"/shared_state.bin":"/initial_state.bin"),packet);auto before=f.coefficient;auto a=load_acceleration(pressure+"/"+name+"/acceleration.csv",f);auto points=positive_points(packet,f,rank,ranks);auto G=gp::geometry(f);auto vv=hessian_velocity(f,G);std::vector<PointTemporal>temporal(points.size());
            #pragma omp parallel for schedule(static)
            for(size_t i=0;i<points.size();i++)temporal[i]=point_temporal(f,points[i],a);
            R sum[24][4]={};for(size_t i=0;i<points.size();i++){int c=f.triangle[points[i].triangle].cell;R w=points[i].weight;sum[c][0]+=w;sum[c][1]+=w*temporal[i].p.J;sum[c][2]+=w*temporal[i].Jdot;sum[c][3]+=w*temporal[i].Jddot;}MPI_Allreduce(MPI_IN_PLACE,sum,24*4,MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);std::vector<Temporal>cell(24);
            for(int c=0;c<24;c++){auto&t=cell[c];t.A=sum[c][0];t.QJ=sum[c][1];t.QdJ=sum[c][2];t.QddJ=sum[c][3];t.Vdd=vv[c];for(auto&entry:G.G[c])t.Vdd+=entry.second[0]*a[0][entry.first]+entry.second[1]*a[1][entry.first];t.delta=(G.volume[c]-t.QJ)/t.A;t.delta_dot=(G.vdot[c]-t.QdJ)/t.A;t.delta_ddot=(t.Vdd-t.QddJ)/t.A;}
            R maximum[3]={},means[24][3]={};struct Witness {R chi=0,material=0,correction=0,nu_relative_dot=0,nu_relative_ddot=0;double X=0,Y=0;uint64_t source=0,cell=0;};Witness witness;
            for(size_t i=0;i<points.size();i++){const auto&q=points[i];const auto&p=temporal[i];int c=f.triangle[q.triangle].cell;auto&t=cell[c];R Jnu=R(p.p.J)+t.delta,dnu=p.Jdot+t.delta_dot,ddnu=p.Jddot+t.delta_ddot,gamma=packet.parameters[1],newcurvature=gamma*(gamma+1)*(dnu/Jnu)*(dnu/Jnu)-gamma*ddnu/Jnu,oldcurvature=gamma*(gamma+1)*(p.Jdot/p.p.J)*(p.Jdot/p.p.J)-gamma*p.Jddot/p.p.J,x=state?p.p.position[0]:q.X,y=state?p.p.position[1]:q.Y,z=x*x+y*y+R(packet.parameters[3])*packet.parameters[3],omega2=powl(z,-1.5L),chi=fabsl(newcurvature)/omega2,material=fabsl(oldcurvature)/omega2,correction=fabsl(newcurvature-oldcurvature)/omega2;need(Jnu>0,"positive temporal thermodynamic measure");maximum[0]=std::max(maximum[0],chi);maximum[1]=std::max(maximum[1],material);maximum[2]=std::max(maximum[2],correction);means[c][0]+=R(q.weight)*chi;means[c][1]+=R(q.weight)*correction;means[c][2]+=R(q.weight)*ddnu;if(chi>witness.chi)witness={chi,material,correction,dnu/Jnu,ddnu/Jnu,q.X,q.Y,uint64_t(q.triangle),f.cell[c]};}
            MPI_Allreduce(MPI_IN_PLACE,maximum,3,MPI_LONG_DOUBLE,MPI_MAX,MPI_COMM_WORLD);MPI_Allreduce(MPI_IN_PLACE,means,24*3,MPI_LONG_DOUBLE,MPI_SUM,MPI_COMM_WORLD);std::vector<Witness>witnesses(rank==0?ranks:0);MPI_Gather(&witness,sizeof(witness),MPI_BYTE,witnesses.data(),sizeof(witness),MPI_BYTE,0,MPI_COMM_WORLD);need(!memcmp(before.data(),f.coefficient.data(),before.size()*sizeof(STCoefficient)),"saved state unchanged by temporal gate");
            if(rank==0){R mean=0,correction_mean=0,volume2identity=0;FILE*out=fopen((dest+"/"+name+"_cells.csv").c_str(),"w");need(out,"actual nu curvature cell ledger");fprintf(out,"cell,A,QJ,delta_J,delta_Jdot,delta_Jddot,boundary_Vddot,quadrature_Jddot,Hessian_v_v,mean_nu_curvature_chi,mean_nu_vs_material_correction_chi,sum_nuddot_minus_boundary_Vddot\n");for(int c=0;c<24;c++){const auto&t=cell[c];mean=std::max(mean,means[c][0]/t.A);correction_mean=std::max(correction_mean,means[c][1]/t.A);volume2identity=std::max(volume2identity,fabsl(means[c][2]-t.Vdd)/t.A);fprintf(out,"%llu,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg,%.21Lg\n",(unsigned long long)f.cell[c],t.A,t.QJ,t.delta,t.delta_dot,t.delta_ddot,t.Vdd,t.QddJ,vv[c],means[c][0]/t.A,means[c][1]/t.A,means[c][2]-t.Vdd);}fclose(out);witness=*std::max_element(witnesses.begin(),witnesses.end(),[](const Witness&a,const Witness&b){return a.chi<b.chi;});bool pass=(state||(maximum[0]<=.002L&&mean<=.001L))&&maximum[2]<=.002L&&correction_mean<=.001L&&volume2identity<1e-12L;all=all&&pass;
                out=fopen((dest+"/"+name+"_result.json").c_str(),"w");need(out,"actual thermal curvature result");fprintf(out,"{\"scope\":\"SAVED %s and SAVED compatible acceleration; exact chosen quadratic boundary functional Hessian contraction; no state/RHS update\",\"MPI_ranks\":%d,\"initial_Kepler_reference_gate_applied\":%s,\"actual_nu_pressure_curvature_chi_max\":%.21Lg,\"actual_nu_every_cell_mean_chi_max\":%.21Lg,\"material_J_pressure_curvature_chi_max\":%.21Lg,\"nu_vs_material_curvature_correction_chi_max\":%.21Lg,\"every_cell_mean_correction_chi_max\":%.21Lg,\"sum_nuddot_boundary_identity_over_area\":%.21Lg,\"worst_source\":%llu,\"worst_cell\":%llu,\"X\":%.17g,\"Y\":%.17g,\"worst_nudot_over_nu\":%.21Lg,\"worst_nuddot_over_nu\":%.21Lg,\"actual_nu_temporal_gate_pass\":%s}\n",name.c_str(),ranks,state?"false":"true",maximum[0],mean,maximum[1],maximum[2],correction_mean,volume2identity,(unsigned long long)witness.source,(unsigned long long)witness.cell,witness.X,witness.Y,witness.nu_relative_dot,witness.nu_relative_ddot,pass?"true":"false");fclose(out);}
        }if(rank==0){printf("{\"scope\":\"actual nu thermodynamic second-time-derivative on two immutable saved controls\",\"MPI_ranks\":%d,\"actual_nu_curvature_bundle_pass\":%s,\"no_mass_or_force_solve\":true,\"long_Kepler_validated\":false}\n",ranks,all?"true":"false");code=all?0:2;}MPI_Bcast(&code,1,MPI_INT,0,MPI_COMM_WORLD);
    }catch(const std::exception&e){fprintf(stderr,"rank%d FAIL %s\n",rank,e.what());MPI_Abort(MPI_COMM_WORLD,2);}MPI_Finalize();return code;
}
